constexpr double L=.025,E=2.129e9,I=3.960e-12,area=3.449e-6,radius=.00185,density=1200,delta=.000025,dh=.00000001;
DiscreteElasticRodModel model(unsigned n){DiscreteRodMaterial mat{.radius=radius,.density=density,.youngModulus=E,.poissonRatio=.35};auto m=makeStraightSutureRod(n,L,mat);m.name="related_crow_rachis_energy_instrument";m.fidelityBoundary="uniform short-segment surrogate; carrion crow sample";std::fill(m.bendStiffness.begin(),m.bendStiffness.end(),E*I);std::fill(m.stretchStiffness.begin(),m.stretchStiffness.end(),E*area);double dm=density*area*L/(n-1);for(unsigned j=0;j<n;++j)m.nodeMasses[j]=(j==0||j==n-1)?.5*dm:dm;return m;}
DiscreteElasticRodState shaped(const DiscreteElasticRodModel&m,double d){auto s=makeDiscreteElasticRodDefaultState(m);for(auto& p:s.positions){double x=p[0]/L;if(x>.5)x=1-x;p[1]=d*(3*x-4*x*x*x);}return s;}
double energy(const DiscreteElasticRodModel&m,double d){auto s=shaped(m,d);DiscreteElasticRodEnergy e;auto diag=evaluateDiscreteElasticRodEnergy(m,s,e);if(!diag.succeeded())throw std::runtime_error("energy reference failed");return e.total();}
void stateJson(const DiscreteElasticRodState&s){std::cout<<"[";for(size_t i=0;i<s.positions.size();++i){if(i)std::cout<<',';std::cout<<'[';for(int j=0;j<3;++j)std::cout<<s.positions[i][j]<<',';for(int j=0;j<3;++j){if(j)std::cout<<',';std::cout<<s.velocities[i][j];}std::cout<<']';}std::cout<<']';}
int main(int argc,char**argv){try{if(argc!=4)throw std::runtime_error("expected metallib, mode, offset");int chosen=std::stoi(argv[2]);double offset=std::stod(argv[3]);std::cout<<std::setprecision(14);auto bird=makeCrowArticulatedWingMechanicsFixture(crowHipRollModel());auto&bm=bird.mechanics;bm.world.gravityAndTimestep.x=bm.world.gravityAndTimestep.y=bm.world.gravityAndTimestep.z=0;auto rodm=model(9);auto initial=shaped(rodm,0);for(auto &p:initial.positions)p[1]+=offset;HeterogeneousRodProgram rod;rod.instanceId="rachis_segment";rod.model=rodm;rod.defaultState=initial;rod.stepConfig.timestep=.001;rod.stepConfig.gravity={0,0,0};rod.stepConfig.solverIterations=4096;rod.stepConfig.constraintTolerance=1e-10;rod.stepConfig.linearDamping=100;rod.stepConfig.twistDamping=100;rod.collision.enableToolCollision=false;rod.collision.enableCCD=false;rod.attachments={{.nodeIndex=0,.targetPosition={0,0,0}},{.nodeIndex=4,.targetPosition={L/2,0,0}},{.nodeIndex=8,.targetPosition={L,0,0}}};rod.rigidBindings.resize(3);std::array<HeterogeneousWorldComponent,1> components{{{.model=&bm,.instanceId="v15_crow"}}};std::array<HeterogeneousRodProgram,1> rods{rod};EngineModelComposeConfig cc;cc.name="crow_rachis_supported_probe";cc.gravityAndTimestep={0,0,0,.001f};HeterogeneousWorld world;auto cd=composeHeterogeneousWorld(components,rods,world,cc);std::cout<<"{\"event\":\"compose\",\"ok\":"<<(cd.succeeded()?"true":"false")<<",\"message\":"<<std::quoted(cd.message)<<",\"fingerprint\":"<<cd.fingerprint<<"}"<<std::endl;if(!cd.succeeded())return 2;CompiledWorld compiled;auto co=compileMetalWorld(world,compiled);std::cout<<"{\"event\":\"compile\",\"ok\":"<<(co.succeeded()?"true":"false")<<",\"message\":"<<std::quoted(co.message)<<",\"fingerprint\":"<<co.fingerprint<<"}"<<std::endl;if(!co.succeeded())return 2;auto &art=bm.articulations[0];std::vector<float>effort(art.nv,0);MetalWorldBatch batch;batch.environmentCount=1;batch.controlStepCount=1;batch.initialQ=bm.defaultQ;batch.initialV=bm.defaultV;batch.efforts=effort;MetalWorldConfig mc;mc.metallibPath=argv[1];mc.preferParallelABA=false;bool overall=true;for(int trial=0;trial<1;++trial){int mode=chosen;MetalWorldContext context(mc);MetalWorldStepConfig cfg;cfg.timestepSeconds=.001f;cfg.physicsSubsteps=1;cfg.solverMode=mode==0?MetalWorldSolverMode::temporalCone:MetalWorldSolverMode::qualityNewton;cfg.applyBodyDamping=false;cfg.captureContactEvidence=true;MetalWorldResult out;auto d=context.run(compiled,batch,cfg,out);bool ok=d.succeeded()&&d.dispatched&&d.published&&d.successfulStepCount==1&&d.failedStepCount==0&&out.finalRodNodes.size()==9&&out.finalRodEdges.size()==8;std::cout<<"{\"event\":\"run\",\"mode\":"<<std::quoted(mode==0?"temporalCone":"qualityNewton")<<",\"initial_offset\":"<<offset<<",\"ok\":"<<(ok?"true":"false")<<",\"succeeded\":"<<(d.succeeded()?"true":"false")<<",\"dispatched\":"<<(d.dispatched?"true":"false")<<",\"published\":"<<(d.published?"true":"false")<<",\"steps\":"<<d.successfulStepCount<<",\"failed\":"<<d.failedStepCount<<",\"status\":"<<d.firstGPUStatusCode<<",\"message\":"<<std::quoted(d.message)<<",\"rod_statuses\":[";for(size_t k=0;k<out.rodStatuses.size();++k){auto &s=out.rodStatuses[k];if(k)std::cout<<',';std::cout<<"{\"code\":"<<s.code<<",\"environment\":"<<s.environment<<",\"iterations\":"<<s.iterations<<",\"failing_index\":"<<s.failingIndex<<",\"diagnostics\":["<<s.diagnostics.x<<','<<s.diagnostics.y<<','<<s.diagnostics.z<<','<<s.diagnostics.w<<"]}";}std::cout<<']';if(ok){auto state=initial;for(int i=0;i<9;++i){auto&x=out.finalRodNodes[i];state.positions[i]={x.position.x,x.position.y,x.position.z};state.velocities[i]={x.velocity.x,x.velocity.y,x.velocity.z};}for(int i=0;i<8;++i){state.twists[i]=out.finalRodEdges[i].twistAndRate.x;state.twistRates[i]=out.finalRodEdges[i].twistAndRate.y;}DiscreteElasticRodEnergy e,b;if(!evaluateDiscreteElasticRodEnergy(rodm,state,e).succeeded()||!evaluateDiscreteElasticRodEnergy(rodm,initial,b).succeeded())throw std::runtime_error("energy failed");double k=0;for(int i=0;i<9;++i)for(int j=0;j<3;++j)k+=.5*rodm.nodeMasses[i]*state.velocities[i][j]*state.velocities[i][j];for(int i=0;i<8;++i)k+=.5*rodm.edgeRotationalInertias[i]*state.twistRates[i]*state.twistRates[i];std::cout<<",\"before\":"<<b.total()<<",\"after\":"<<e.total()<<",\"kinetic\":"<<k<<",\"node_forces\":[";for(int i=0;i<9;++i){auto p=state;double h=1e-9;p.positions[i][1]+=h;DiscreteElasticRodEnergy ep,em;if(!evaluateDiscreteElasticRodEnergy(rodm,p,ep).succeeded())throw std::runtime_error("plus");p.positions[i][1]-=2*h;if(!evaluateDiscreteElasticRodEnergy(rodm,p,em).succeeded())throw std::runtime_error("minus");if(i)std::cout<<',';std::cout<<-(ep.total()-em.total())/(2*h);}std::cout<<"],\"state\":";stateJson(state);std::cout<<",\"twists\":[";for(size_t i=0;i<state.twists.size();++i){if(i)std::cout<<',';std::cout<<'['<<state.twists[i]<<','<<state.twistRates[i]<<']';}std::cout<<']';}std::cout<<"}"<<std::endl;overall=overall&&ok;}return overall?0:2;}catch(const std::exception&e){std::cerr<<"exception: "<<e.what()<<'\n';return 1;}}